"""Bundle the fixed Quill modules without a third-party build dependency."""
from pathlib import Path
root=Path(__file__).resolve().parent.parent/'docs'
def module(name,imports,exports):
    source=(root/(name+'.js')).read_text()
    source='\n'.join(line for line in source.splitlines() if not line.startswith('import '))
    source=source.replace('export async function ','async function ').replace('export function ','function ').replace('export const ','const ')
    namespace='AIRuntime' if name=='ai-runtime' else name.title()
    return f'const Quill{namespace} = (() => {{\n{imports}\n{source}\nreturn {{{exports}}};\n}})();\n'
source='// Generated by scripts/bundle.py. Edit the source modules, then rebuild.\n'
source+=module('core','', 'uuid,validate,union,heads,documents,revise,countWords,escapeXML,fromBackup,backup,zip,isManagedDraft,purgeDraft,draftStorage')
source+=module('storage','const {union,validate}=QuillCore;', 'native,bridge,openStorage,load,put,connectFolder,disconnectFolder,sync,download')
source+=module('export','const {zip,escapeXML:x}=QuillCore;', 'sanitize,plain,manuscriptHTML,epub,docx')
source+=module('editing','const {sanitize}=QuillExport;', 'textMap,textRange,isSingleWord,manuscriptText,findText,replaceText,spellingWords,spellingEngine,personalWords,rememberWord')
source+=module('writing','const {escapeXML,uuid}=QuillCore;', 'sectionTypes,sectionLabel,sectionGroup,sectionOrder,sectionTemplate,manuscriptBeats,joinBeats,planLines,applyBeatPlan,parseAnalysis,normalizedName')
source+=module('icons','', 'controlIcons,actionIcons,buttonIconName')
source+=module('drafts','', 'draftKind,draftMatches,downloadProgress')
source+=module('codex','', 'characterFields,characterContext,parseCharacter,portraitPrompt')
source+=module('models','', 'localModels,isLocalModel,validateConnection,apiRequest,apiText')
source+=module('connections','const {native,bridge}=QuillStorage; const {validateConnection,apiRequest,apiText}=QuillModels;', 'loadConnections,connections,saveConnection,deleteConnection,remoteRequest')
source+=module('quality','', 'defaultAvoidPhrases,avoidPhrases,repeatedPhrases,beatProblems,parseBeatReview')
source+=module('ai','const {countWords,escapeXML}=QuillCore; const {characterContext}=QuillCodex; const {defaultAvoidPhrases,avoidPhrases,beatProblems,parseBeatReview}=QuillQuality;', 'defaultBeatPrompt,chapterLengths,textToHTML,canUseDraft,chunkText,buildChapterContext,generateChapter,generateChapterOutline,generateCodex,outlineLimit,generateBeat,revisePassage,analyzeManuscript,suggestAlternatives,parseAlternatives')
source+=module('ai-runtime','const {native,bridge}=QuillStorage; const {localModels,isLocalModel}=QuillModels; const {connections,remoteRequest}=QuillConnections;', 'modelChoices,checkModel,createWriter,releaseQwen,checkQwenUpdate,updateQwen,modelStorage,deleteModel')
app='\n'.join(line for line in (root/'app.js').read_text().splitlines() if not line.startswith('import '))
source+='(() => {\nconst {uuid,union,heads,documents,revise,countWords,backup,fromBackup,purgeDraft,draftStorage,escapeXML:esc}=QuillCore;\nconst storage=QuillStorage;\nconst {defaultAvoidPhrases,avoidPhrases}=QuillQuality;\nconst {textMap,textRange,isSingleWord,manuscriptText,findText,replaceText,spellingWords,spellingEngine,personalWords,rememberWord}=QuillEditing;\nconst {sectionTypes,sectionLabel,sectionGroup,sectionOrder,sectionTemplate,manuscriptBeats,joinBeats,planLines,applyBeatPlan,parseAnalysis,normalizedName}=QuillWriting;\nconst {controlIcons,actionIcons,buttonIconName}=QuillIcons;\nconst {draftKind,draftMatches,downloadProgress}=QuillDrafts;\nconst {characterFields,characterContext,parseCharacter,portraitPrompt}=QuillCodex;\nconst {localModels,isLocalModel}=QuillModels;\nconst {loadConnections,connections,saveConnection,deleteConnection}=QuillConnections;\nconst {defaultBeatPrompt,chapterLengths,textToHTML,canUseDraft,buildChapterContext,generateChapter,generateChapterOutline,generateCodex,outlineLimit,generateBeat,revisePassage,analyzeManuscript,suggestAlternatives,parseAlternatives}=QuillAi;\nconst {modelChoices,checkModel,createWriter,checkQwenUpdate,updateQwen,modelStorage,deleteModel}=QuillAIRuntime;\nconst {sanitize,plain,manuscriptHTML,epub,docx}=QuillExport;\n'+app+'\n})();\n'
(root/'app.bundle.js').write_text(source)
